if(args.Length!=2)throw new ArgumentException("Usage: NonImageGraphProbe <workspace> <report>");
string workspace=Path.GetFullPath(args[0]),reportPath=Path.GetFullPath(args[1]);
var cases=new List<object>();
void Check(bool condition,string name,object observation){if(!condition)throw new InvalidOperationException("CHECK FAILED: "+name);cases.Add(new{name,passed=true,observation});}
string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
async Task<PairRun> Run(PortValue value,PortDescriptor target,bool mutateParameters=false,bool throwInSource=false,bool local=false){
 var log=new List<string>();var reg=new ModuleRegistry();var source=new ModuleDescriptor("probe.source","1","Synthetic producer",[],[new("Out",value.Kind){Cardinality=value.Cardinality}],[]);
 var sink=new ModuleDescriptor("probe.sink","1","Synthetic consumer",[target],[new("Echo",target.Kind){Cardinality=target.Cardinality}],[new("Gain",ParameterKind.Integer,false)]);
 var originalParameters=new Dictionary<string,JsonElement>{{"Gain",JsonSerializer.SerializeToElement(7)}};
 var sourceTable=new Dictionary<string,PortValue>{{"Out",value}};var sinkTable=new Dictionary<string,PortValue>();ModuleExecutionContext? seen=null;int sourceCreated=0,sinkCreated=0,sourceDisposed=0,sinkDisposed=0;
 reg.Register(source,()=>{sourceCreated++;return new ProbeModule(source,ctx=>{log.Add("source.execute");if(mutateParameters)originalParameters["Gain"]=JsonSerializer.SerializeToElement(99);if(throwInSource)throw new InvalidOperationException("synthetic-source-failure");return new(ModuleStatus.Success,sourceTable);},()=>{sourceDisposed++;log.Add("source.dispose");});});
 reg.Register(sink,()=>{sinkCreated++;return new ProbeModule(sink,ctx=>{log.Add("sink.execute");seen=ctx;sinkTable["Echo"]=ctx.Inputs["Input"];return new(ModuleStatus.Success,sinkTable);},()=>{sinkDisposed++;log.Add("sink.dispose");});});
 var config=new WorkflowConfiguration{Outputs=[new("output","Published",target.Kind,"sink","Echo"){Cardinality=target.Cardinality}],Displays=[new("display","Preview",target.Kind,"sink","Echo"){Cardinality=target.Cardinality}],Groups=local?[new("group","General")]:[],Variables=local?[new("variable","group","Counter","int","0",SourceNode:"source",SourcePort:"Out")]:[]};
 var graph=new ProcedureDocument("probe-flow","Synthetic two-node transport",[new("source",source.Id,"1","Source",new()),new("sink",sink.Id,"1","Sink",originalParameters)],[new("source","Out","sink","Input")],[new("source","sink")]){Configuration=config};
 using var scope=new ModuleExecutionScope();var session=await new GraphExecutor(reg).RunAsync(graph,workspace,scope:scope);
 return new(session,seen,sourceTable,sinkTable,originalParameters,log,sourceCreated,sinkCreated,sourceDisposed,sinkDisposed);
}
var text=new string(new[]{'a','b','c'});var texts=PortValue.TextArray(new[]{text});var shared=await Run(texts,new("Input",DataKind.Text){Cardinality=ValueCardinality.Array},mutateParameters:true);
Check(shared.Session.Status==SessionStatus.Success&&ReferenceEquals(shared.Context!.Inputs["Input"],texts)&&ReferenceEquals(shared.Session.Nodes.Single(n=>n.NodeId=="source").Outputs["Out"],texts)&&ReferenceEquals(shared.Session.WorkflowOutputs["Published"],texts)&&ReferenceEquals(shared.Session.WorkflowDisplays["Preview"][0],texts),"Graph carries one TextArray PortValue through node input, result and workflow display projection",new{samePortValue=true,sameString=ReferenceEquals(shared.Context!.Inputs["Input"].As<IReadOnlyList<string>>()[0],text),note="Workflow display projection is data only; no WPF renderer was started."});
Check(shared.SourceDisposed==1&&shared.SinkDisposed==1&&shared.Log.SequenceEqual(new[]{"source.execute","source.dispose","sink.execute","sink.dispose"}),"Runtime modules dispose before later nodes while session payload stays reachable",new{shared.SourceDisposed,shared.SinkDisposed,order=shared.Log,payloadAfterDisposal=shared.Session.WorkflowOutputs["Published"].As<IReadOnlyList<string>>()[0]});
Check(!ReferenceEquals(shared.SourceTable,shared.Session.Nodes.Single(n=>n.NodeId=="source").Outputs)&&!ReferenceEquals(shared.SinkTable,shared.Session.Nodes.Single(n=>n.NodeId=="sink").Outputs),"Graph result records own copied dictionaries",new{sameSourceDictionary=false,sameSinkDictionary=false});
shared.SourceTable.Clear();shared.SinkTable.Clear();
Check(ReferenceEquals(shared.Session.Nodes.Single(n=>n.NodeId=="source").Outputs["Out"],texts)&&ReferenceEquals(shared.Session.WorkflowOutputs["Published"],texts),"Clearing synthetic module dictionaries leaves session references intact",new{sessionStillContainsOriginal=true});
Check(shared.OriginalParameters["Gain"].GetInt32()==99&&shared.Context!.Parameters["Gain"].GetInt32()==7,"Procedure snapshot isolates downstream parameter dictionary from in-run editor mutation",new{original=99,executed=7});
var array=await Run(PortValue.IntegerArray(new long[]{1,2}),new("Input",DataKind.Number,AcceptInteger:true){Cardinality=ValueCardinality.Array});var failed=array.Session.Nodes.Single(n=>n.NodeId=="sink");
Check(array.Session.Status==SessionStatus.Failed&&failed.Status==NodeRunStatus.Failed&&failed.ErrorCode=="InputTypeMismatch"&&array.SinkCreated==0&&array.SourceDisposed==1,"Integer-array coercion failure is recorded before consumer factory creation",new{session=array.Session.Status.ToString(),node=failed.Status.ToString(),failed.ErrorCode,failed.Message,array.SinkCreated,array.SourceDisposed,outputErrors=array.Session.OutputErrors});
var promoted=await Run(PortValue.Integer(16_777_217),new("Input",DataKind.Number,AcceptInteger:true));
Check(promoted.Session.Status==SessionStatus.Success&&promoted.Context!.Inputs["Input"].As<double>()==16_777_216,"Graph integer promotion observes the float intermediate",new{input=16_777_217,actual=promoted.Context!.Inputs["Input"].As<double>()});
var boundValue=PortValue.Integer(42);var bound=await Run(boundValue,new("Input",DataKind.Integer),local:true);
Check(bound.Session.Status==SessionStatus.Success&&ReferenceEquals(bound.Session.LocalVariables["Counter"],boundValue)&&ReferenceEquals(bound.Session.WorkflowOutputs["Published"],boundValue),"Bound local variable and workflow result retain the same current-run PortValue after module disposal",new{sameLocalValue=true,samePublishedValue=true,bound.SourceDisposed,bound.SinkDisposed});
var thrown=await Run(PortValue.Text("value"),new("Input",DataKind.Text),throwInSource:true);
Check(thrown.Session.Status==SessionStatus.Failed&&thrown.Session.Nodes.Single(n=>n.NodeId=="source").ErrorCode=="ModuleException"&&thrown.Session.Nodes.Single(n=>n.NodeId=="sink").Status==NodeRunStatus.Skipped&&thrown.SourceDisposed==1&&thrown.SinkCreated==0,"Throwing producer is disposed and its consumer is skipped",new{sourceError=thrown.Session.Nodes.Single(n=>n.NodeId=="source").ErrorCode,sink=thrown.Session.Nodes.Single(n=>n.NodeId=="sink").Status.ToString(),thrown.SourceDisposed,thrown.SinkCreated});

var assemblies=new List<object>();var sourcePaths=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
foreach(var assembly in new[]{typeof(PortValue).Assembly,typeof(Point2).Assembly,Assembly.GetExecutingAssembly()}.Distinct()){
 string dll=assembly.Location,pdb=Path.ChangeExtension(dll,"pdb");
 using var peStream=File.OpenRead(dll);using var pe=new PEReader(peStream);var debug=pe.ReadDebugDirectory().Single(e=>e.Type==DebugDirectoryEntryType.CodeView);var cv=pe.ReadCodeViewDebugDirectoryData(debug);
 using var pdbStream=File.OpenRead(pdb);using var provider=MetadataReaderProvider.FromPortablePdbStream(pdbStream);var reader=provider.GetMetadataReader();var id=new BlobContentId(reader.DebugMetadataHeader!.Id);if(cv.Guid!=id.Guid||debug.Stamp!=id.Stamp)throw new InvalidDataException("DLL/PDB mismatch");
 var docs=new List<object>();foreach(var h in reader.Documents){var doc=reader.GetDocument(h);string p=reader.GetString(doc.Name);var algorithm=reader.GetGuid(doc.HashAlgorithm);var bytes=File.ReadAllBytes(p);var actual=algorithm==new Guid("8829d00f-11b8-4213-878b-770e8597ac16")?SHA256.HashData(bytes):algorithm==new Guid("ff1816ec-aa5e-4d10-87f7-6f4963833460")?SHA1.HashData(bytes):throw new InvalidDataException("Unknown checksum");if(!actual.SequenceEqual(reader.GetBlobBytes(doc.Hash)))throw new InvalidDataException("Current source changed: "+p);sourcePaths.Add(p);docs.Add(new{path=p,sha256=Hash(p),currentFileMatched=true});}
 assemblies.Add(new{path=dll,sha256=Hash(dll),pdbPath=pdb,pdbSha256=Hash(pdb),mvid=assembly.ManifestModule.ModuleVersionId,pdbMatchesLoadedDll=true,sourceDocuments=docs});
}
string[] required={"src/VisionFramework/GraphExecutor.cs","src/VisionFramework/WorkflowRunContext.cs","src/VisionFramework/Contracts.cs","src/VisionFramework/PortArrays.cs"};foreach(var p in required)if(!sourcePaths.Contains(Path.Combine(workspace,p.Replace('/',Path.DirectorySeparatorChar))))throw new InvalidDataException("Required compiled implementation absent: "+p);
var report=new{schemaVersion=1,scope="Finite synthetic two-node graphs executed by real current-main GraphExecutor",passed=cases.Count,failed=0,cases,assemblies,requiredImplementationSources=required.Select(p=>new{path=p,sha256=Hash(Path.Combine(workspace,p))}),runtimeExecuted=true,graphExecutorExecuted=true,vendorRuntimeExecuted=false,guiStarted=false,deviceCalled=false,productModified=false,implementationCredit=0,limitations=new[]{"Synthetic source/consumer modules exercise current framework transport only, not any shipped tool algorithm, original program, native module, WPF renderer or device.","WorkflowDisplays is the returned data projection; no history service, UI result panel or final rendering was exercised.","Dispose counters belong to runtime module instances. Retained session references do not prove GC timing, native pixel release or last-reader retirement.","Finite two-node runs do not establish full solution/Group scheduling, cancellation races, native ABI or vendor parity."}};
Directory.CreateDirectory(Path.GetDirectoryName(reportPath)!);File.WriteAllText(reportPath,JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{passed=cases.Count,failed=0,assemblies=assemblies.Count,sourceDocuments=sourcePaths.Count,report=reportPath}));
sealed record PairRun(ExecutionSessionResult Session,ModuleExecutionContext? Context,Dictionary<string,PortValue> SourceTable,Dictionary<string,PortValue> SinkTable,Dictionary<string,JsonElement> OriginalParameters,List<string> Log,int SourceCreated,int SinkCreated,int SourceDisposed,int SinkDisposed);
sealed class ProbeModule(ModuleDescriptor descriptor,Func<ModuleExecutionContext,ModuleResult> execute,Action dispose):IModule,IAsyncDisposable{public ModuleDescriptor Descriptor=>descriptor;public ValueTask<ModuleResult> ExecuteAsync(ModuleExecutionContext context,CancellationToken cancellationToken)=>ValueTask.FromResult(execute(context));public ValueTask DisposeAsync(){dispose();return ValueTask.CompletedTask;}}

